style:
/* 蓝辙 —— 日期独立左栏，通栏虚线导轨与同心圆节点 */

.tw-lanzhe.layout-academic.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4mm;
  border-bottom: 0.25mm solid #dbe7ee;
}

.tw-lanzhe.layout-academic.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 6mm;
}

.tw-lanzhe.layout-academic.resume-paper .paper-header__main {
  flex: 1 1 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
  min-width: 0;
}

/* 证件照收到右上角：参考稿的姓名在左，照片与页眉同高 */
.tw-lanzhe.layout-academic.resume-paper .paper-photo {
  order: 3;
  margin-left: auto;
  width: 25mm;
  height: 33mm;
  border: 0.4mm solid #d9e5ec;
  box-shadow: none;
}

.tw-lanzhe.layout-academic.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef4f7;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-lanzhe.layout-academic.resume-paper .paper-name-row {
  flex: 0 0 auto;
}

.tw-lanzhe.layout-academic.resume-paper .paper-name {
  color: var(--paper-accent);
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.15);
  letter-spacing: 0.06em;
}

.tw-lanzhe.layout-academic.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #5d7079;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-lanzhe.layout-academic.resume-paper .paper-role {
  flex: 0 0 auto;
  margin-top: 0;
  color: #24343c;
  font-size: calc(var(--paper-base-size) * 1.02);
  font-weight: 600;
  letter-spacing: 0.03em;
}

.tw-lanzhe.layout-academic.resume-paper .paper-role::before {
  content: "求职岗位：";
  color: #7a8b93;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-lanzhe.layout-academic.resume-paper .paper-contacts {
  display: grid;
  flex: 1 0 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 4mm;
  color: #31434c;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-lanzhe.layout-academic.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
}

.tw-lanzhe.layout-academic.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-lanzhe.layout-academic.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: var(--paper-accent);
}

/* 每块内容挂一条虚线导轨，节点压在标题行左侧 */
.tw-lanzhe.layout-academic.resume-paper .paper-section {
  position: relative;
  padding-left: 7mm;
  border-left: 0.25mm dashed color-mix(in srgb, var(--paper-accent) 72%, #fff);
}

.tw-lanzhe.layout-academic.resume-paper .paper-style-caps .paper-section__title {
  position: relative;
  margin-bottom: 3.2mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.28mm solid color-mix(in srgb, var(--paper-accent) 62%, #fff);
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.1);
  letter-spacing: 0.12em;
}

.tw-lanzhe.layout-academic.resume-paper .paper-style-caps .paper-section__title::before {
  content: "";
  position: absolute;
  top: -1.1mm;
  left: -9.1mm;
  width: 4.2mm;
  height: 4.2mm;
  border-radius: 50%;
  background: radial-gradient(circle, var(--paper-accent) 0 22%, #fff 23% 45%, var(--paper-accent) 46% 66%, #fff 67% 100%);
  box-shadow: 0 0 0 1.1mm #fff;
  print-color-adjust: exact;
}

.tw-lanzhe.layout-academic.resume-paper .paper-section__body {
  color: #2f3d45;
}

/* 条目：日期左栏加宽，单位与岗位右侧对齐 */
.tw-lanzhe.layout-academic.resume-paper .paper-item {
  display: grid;
  grid-template-columns: 35mm minmax(0, 1fr);
  column-gap: 3mm;
  align-items: baseline;
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-head {
  display: contents;
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-period {
  grid-column: 1;
  grid-row: 1 / span 6;
  padding-top: 0.4mm;
  color: #7f8f97;
  font-size: calc(var(--paper-base-size) * 0.8);
  line-height: 1.5;
  white-space: nowrap;
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-title,
.tw-lanzhe.layout-academic.resume-paper .paper-item-sub,
.tw-lanzhe.layout-academic.resume-paper .paper-meta-line,
.tw-lanzhe.layout-academic.resume-paper .paper-note,
.tw-lanzhe.layout-academic.resume-paper .paper-rich,
.tw-lanzhe.layout-academic.resume-paper .paper-facts {
  grid-column: 2;
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-title {
  color: #22313a;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-sub {
  color: #41535c;
}

.tw-lanzhe.layout-academic.resume-paper .paper-item-sub span + span::before {
  content: "|";
  margin: 0 2.4mm;
  color: #c5d3d9;
}

.tw-lanzhe.layout-academic.resume-paper .paper-rich ul,
.tw-lanzhe.layout-academic.resume-paper .paper-rich ol {
  margin-top: 1mm;
  padding-left: 0;
  list-style: none;
}

.tw-lanzhe.layout-academic.resume-paper .paper-rich li {
  position: relative;
  margin: 0.8mm 0;
  padding-left: 3.6mm;
}

.tw-lanzhe.layout-academic.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.76em;
  left: 0.6mm;
  width: 1.2mm;
  height: 1.2mm;
  border-radius: 50%;
  background: var(--list-color, color-mix(in srgb, var(--paper-accent) 55%, #fff));
  print-color-adjust: exact;
}

/* 技能：五个点连成一条分段进度条 */
.tw-lanzhe.layout-academic.resume-paper .paper-skills {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2mm 10mm;
}

.tw-lanzhe.layout-academic.resume-paper .paper-skill {
  padding-bottom: 1.2mm;
  border-bottom: none;
}

.tw-lanzhe.layout-academic.resume-paper .paper-skill__dots {
  gap: 0;
}

.tw-lanzhe.layout-academic.resume-paper .paper-skill__dots i {
  width: 7mm;
  height: 1.4mm;
  border-radius: 0;
  background: #e3edf1;
}

.tw-lanzhe.layout-academic.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-lanzhe.layout-academic.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

.tw-lanzhe.layout-academic.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2ecf1;
  color: #9aabb3;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-lanzhe.resume-paper .paper-rich ul[data-list],
.tw-lanzhe.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-lanzhe.resume-paper .paper-rich ul[data-list] > li,
.tw-lanzhe.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-lanzhe.resume-paper .paper-rich ul[data-list] > li::before,
.tw-lanzhe.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-lanzhe.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-lanzhe.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-lanzhe.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-lanzhe.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 没有日期的条目（作品集、技能等）不该再占着空的日期列，否则整体右移 */
.tw-lanzhe.resume-paper .paper-item.paper-item--undated {
  grid-template-columns: 0 minmax(0, 1fr);
  column-gap: 0;
}
/* 工作地点上移到标题行：日期 — 单位 — 地点 一行读齐，地点贴最右；副行只留岗位 / 部门 / 性质。 */
.tw-lanzhe.layout-academic.resume-paper .is-work_experience .paper-item {
  grid-template-columns: 35mm minmax(0, 1fr) auto;}
.tw-lanzhe.layout-academic.resume-paper .is-work_experience .paper-item-city {
  display: inline;
  grid-column: 3;
  grid-row: 1;
  justify-self: end;
  color: #7f8f97;
  font-size: calc(var(--paper-base-size) * 0.8);
  white-space: nowrap;}
.tw-lanzhe.layout-academic.resume-paper .is-work_experience .paper-item-sub__city {
  display: none;}
